const $=(selector,root=document)=>root.querySelector(selector),$$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const state={user:null,authReady:false,config:null,home:null,items:new Map(),library:store.get('library_guest',[]),progress:store.get('progress_guest',[]),prefs:store.get('preferences',{motion:true,economy:false}),heroIndex:0,detail:null,comments:[],personalError:''};
const books=new Map(),getCache=new Map(),pending=new Map();
let renderVersion=0,chaptersVersion=0,reader=null,dialog=null,lastFocus=null,avatarObjectUrl=null,avatarUploadController=null,giphyPageController=null,lastProgressSave=0,progressTimer=null,pendingProgress=null,syncWarning=false,importing=false;
