function goBack(){const destination=routeTrail.back();if(location.hash===destination)render();else location.hash=destination;}
function readingProgress(entry){const progress=entry.kind==='progress'?entry:state.progress.find(item=>item.mediaId===entry.mediaId);if(!progress)return '';const percent=Math.max(0,Math.min(100,Number(progress.percent)||0)),page=Math.max(1,Number(progress.page)||1),total=Math.max(page,Number(progress.totalPages)||1);return `<div class="library-read-progress"><div><span>Último capítulo · ${page}/${total} páginas</span><strong>${Math.round(percent)}%</strong></div><progress value="${percent}" max="100" aria-label="Progresso do último capítulo"></progress></div>`;}
function importProgress(label,value){const element=$('#import-progress');if(element){element.hidden=false;element.innerHTML=workProgress(label,value);}}
function photoProgress(label,value){const element=$('#photo-progress');if(element){element.hidden=!label;element.innerHTML=label?workProgress(label,value):'';}}
const isImported=entry=>String(typeof entry==='string'?entry:entry?.mediaId||entry?.id||'').startsWith('import:');
function restoreCollections(){const key=state.user?.id||'guest';state.library=[...store.get('library_'+key,[]).filter(entry=>!isImported(entry)),...store.get('library_imports',[])];state.progress=[...store.get('progress_'+key,[]).filter(entry=>!isImported(entry)),...store.get('progress_imports',[])];}
function persistCollections(){const key=state.user?.id||'guest';store.set('library_'+key,state.library.filter(entry=>!isImported(entry)));store.set('library_imports',state.library.filter(isImported));store.set('progress_'+key,state.progress.filter(entry=>!isImported(entry)));store.set('progress_imports',state.progress.filter(isImported));}

export async function api(path,options={}){
  if(!/^\/api\//.test(path))throw new Error('Endereço de serviço inválido.');
  const body=options.body&&Object.getPrototypeOf(options.body)===Object.prototype?JSON.stringify(options.body):options.body;
  const method=options.method||'GET',cacheable=method==='GET'&&/^\/api\/catalog\//.test(path);
  const cached=getCache.get(path);if(cacheable&&cached&&cached.until>Date.now())return cached.data;
  if(cacheable&&pending.has(path))return pending.get(path);
  const request=(async()=>{
    const response=await fetch(path,{credentials:'same-origin',...options,body,headers:{...(typeof body==='string'?{'Content-Type':'application/json'}:{}),...options.headers},signal:options.signal||AbortSignal.timeout(30000)});
    const data=await response.json().catch(()=>({ok:false,error:'O servidor retornou uma resposta inválida.'}));
    if(!response.ok||data.ok===false)throw Object.assign(new Error(data.error||'Não foi possível concluir. Tente novamente.'),{status:response.status});
    if(cacheable){if(getCache.size>100)getCache.delete(getCache.keys().next().value);getCache.set(path,{data,until:Date.now()+60000});}
    return data;
  })();
  if(cacheable)pending.set(path,request);
  try{return await request;}finally{if(cacheable)pending.delete(path);}
}
const post=(path,body)=>api(path,{method:'POST',body:JSON.stringify(body)});
function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;$('#toast-root').append(el);setTimeout(()=>el.remove(),6500);}
function remember(items=[]){for(const item of items)if(item?.id)state.items.set(String(item.id),item);}
function route(){return parseRoute(location.hash);}
function nav(path){const next='#/'+path.replace(/^\//,'');if(location.hash===next)render();else location.hash=next;}
function applyPrefs(){document.documentElement.classList.toggle('reduce-motion',!state.prefs.motion);document.documentElement.classList.toggle('data-saver',!!state.prefs.economy);}
function collectionScope(){return state.user?'Na sua conta':'Neste dispositivo';}
function badgeScope(){return `<span class="library-scope">${icon(state.user?'profile':'book')}${collectionScope()}</span>`;}
function account(){return state.user?`<a class="profile-chip" href="#/profile">${avatar(state.user)}<b class="${nameClass(state.user.nameColor)}">${esc(state.user.name)}</b></a>`:`<button class="login-link" data-auth="login">Entrar</button><button class="btn primary register-link" data-auth="register">Criar conta</button>`;}
function updateAccount(){const host=$('.header-account');if(host)host.innerHTML=account();}
function brand(){return `<a class="brand" href="#/" aria-label="Mahuwa Dragon, início"><img src="/assets/dragon-mark.webp" alt="" width="36" height="36"><div><strong>Mahuwa<span>Dragon</span></strong><small>Histórias além das fronteiras</small></div></a>`;}
function layout(content,{home=false,reading=false}={}){
  const current=route();document.body.classList.toggle('reader-route',reading);
  const top=[['','Início'],['catalog?kind=manga','Mangás'],['catalog?kind=manhwa','Manhwas'],['catalog?kind=manhua','Manhuas'],['catalog?kind=novel','Novels']];
  const side=[['','home','Início'],['catalog','book','Explorar'],['library','list','Biblioteca'],['import','import','Importar'],['profile','profile','Meu perfil']];
  return `<div class="shell${home?' home-view':''}"><header class="site-header"><div class="masthead"><button class="icon-btn menu-toggle" data-menu aria-label="Abrir menu" aria-expanded="false" aria-controls="main-navigation">${icon('menu')}</button>${brand()}<nav class="top-nav" id="main-navigation" aria-label="Navegação principal">${top.map(([path,label])=>`<a href="#/${path}" class="${(!path&&current.page==='home')||(path&&current.page==='catalog'&&current.params.get('kind')===new URLSearchParams(path.split('?')[1]).get('kind'))?'active':''}">${label}</a>`).join('')}</nav><div class="header-tools"><details class="header-more"><summary aria-label="Mais opções de navegação">${icon('menu')}<span>Mais</span></summary><div class="header-menu"><a href="#/library">${icon('list')} Biblioteca</a><a href="#/import">${icon('import')} Meus arquivos</a><a href="#/settings">${icon('settings')} Preferências</a><a href="#/profile">${icon('profile')} Meu perfil</a></div></details><form class="header-search" id="header-search" role="search"><label class="sr-only" for="global-search">Buscar mangás, manhwas, manhuas e novels</label>${icon('search')}<input id="global-search" type="search" name="q" maxlength="150" autocomplete="off" placeholder="Encontre sua próxima história" value="${esc(current.params.get('q')||'')}"></form><button class="icon-btn search-toggle" data-search-toggle aria-label="Abrir busca" aria-expanded="false">${icon('search')}</button><div class="header-account">${account()}</div></div></div></header><main class="main" id="main-content"><div class="content">${home||reading?'':`<div class="page-navigation">${backButton()}</div>`}<div id="page-content" tabindex="-1">${content}</div>${reading?'':`<footer class="site-footer"><div><a class="footer-brand" href="#/">Mahuwa<span>Dragon</span></a><p>Uma nova história. A cada capítulo.</p></div><div class="footer-links"><a href="#/catalog">Explorar catálogo</a><a href="#/import">Ler meus arquivos</a><a href="#/settings">Preferências</a><span>Catálogo MangaDex · Jikan</span></div></footer>`}</div></main></div>`;
}
function bindShell(){
  const search=$('#header-search');if(search)search.onsubmit=event=>{event.preventDefault();nav('catalog?'+new URLSearchParams({q:$('#global-search').value.trim()}));};
  document.querySelectorAll('img').forEach(image=>image.addEventListener('error',()=>{if(!image.dataset.fallback){image.dataset.fallback='1';image.src='/assets/poster-placeholder.svg';}},{once:true}));
}
function rail(id,title,description,items,{ranking=false,link='catalog'}={}){if(!items?.length)return '';return `<section class="section"><div class="section-head"><div><h2>${esc(title)}</h2><p>${esc(description)}</p></div><a href="#/${link}" class="text-link">Ver todos ${icon('next')}</a></div><div class="catalog-rail"><button class="rail-arrow rail-prev" data-scroll="${id}" data-direction="-1" aria-label="Voltar em ${esc(title)}">${icon('back')}</button><div class="cards" id="${id}" tabindex="0" aria-label="${esc(title)}">${items.map((item,index)=>mediaCard(item,ranking?index:undefined)).join('')}</div><button class="rail-arrow rail-next" data-scroll="${id}" data-direction="1" aria-label="Avançar em ${esc(title)}">${icon('next')}</button></div></section>`;}
function continueReading(){const items=state.progress.filter(progress=>progress.chapterId&&progress.percent<100&&(progress.item||state.items.get(progress.mediaId))).slice(0,10);if(!items.length)return '';return `<section class="section"><div class="section-head"><div><h2>Sua história continua.</h2><p>Volte ao ponto em que parou. ${collectionScope()}.</p></div><a href="#/library?kind=progress" class="text-link">Ver histórico ${icon('next')}</a></div><div class="continue-rail">${items.map(progress=>{const item=progress.item||state.items.get(progress.mediaId);return `<a class="continue-card" href="${readLink(progress.chapterId)}"><img src="${esc(safeUrl(item.coverUrl))}" alt="" loading="lazy"><div><h3>${esc(item.title)}</h3><p>Página ${Math.max(1,Math.min(Number(progress.totalPages)||1,Number(progress.page)||1))} de ${Number(progress.totalPages)||1}</p><progress value="${Math.max(0,Math.min(100,Number(progress.percent)||0))}" max="100" aria-label="Progresso da leitura"></progress></div></a>`;}).join('')}</div></section>`;}
function hero(){const choices=(state.home.featured||[]).length?state.home.featured:(state.home.trending||[]).length?state.home.trending:state.home.originals||[];const item=choices[state.heroIndex%choices.length];if(!item)return empty('O catálogo ainda não carregou.','Tente novamente ou abra seus próprios arquivos.','<button class="btn primary" data-retry="home">Tentar novamente</button>');const score=Number(item.rating)>0?`<span class="score">★ ${Number(item.rating).toFixed(1)}</span>`:'';return `<section class="hero" aria-label="Destaque do catálogo"><img class="hero-art" src="${esc(safeUrl(item.backdropUrl||item.coverUrl,'/assets/dragon-art.webp'))}" alt="" fetchpriority="high"><div class="hero-inner"><span class="eyebrow">UMA HISTÓRIA PARA VOCÊ</span><div class="hero-meta"><span class="badge accent">${kindNames[item.kind]||'Mangá'}</span>${score}<span>${esc(item.year||statusName(item.status))}</span>${item.originLanguage?`<span>${esc(item.originLanguage.toUpperCase())}</span>`:''}</div><h1>${esc(item.title)}</h1><p class="description">${esc(item.description||'Descubra a história, encontre os capítulos disponíveis e prepare sua próxima leitura.')}</p><div class="actions"><a class="btn primary" href="${titleLink(item.id)}">${icon('book')} Explorar capítulos</a><button class="btn ghost" data-save-id="${esc(item.id)}" data-save-kind="later">${icon(hasSaved(item.id,'later')?'check':'plus')}${hasSaved(item.id,'later')?'Na sua lista':'Ler depois'}</button></div>${choices.length>1?`<div class="hero-dots" role="group" aria-label="Destaques">${choices.slice(0,5).map((choice,index)=>`<button data-hero="${index}" aria-label="Mostrar ${esc(choice.title)}" aria-pressed="${state.heroIndex===index}"></button>`).join('')}</div>`:''}</div><span class="hero-source">${item.provider==='local'?'História original · Mahuwa Dragon':`Catálogo ${esc(item.provider||'externo')}`}</span></section>`;}
function homeMarkup(){const data=state.home;return `${hero()}<div class="home-sections"><div class="discovery-strip"><a href="#/catalog?kind=manga"><span>漫</span> Mangás</a><a href="#/catalog?kind=manhwa"><span>✦</span> Manhwas</a><a href="#/catalog?kind=manhua"><span>龍</span> Manhuas</a><a href="#/catalog?kind=novel"><span>▤</span> Novels</a><a href="#/import"><span>＋</span> Meus arquivos</a></div>${continueReading()}${rail('trending','Em alta','Histórias em destaque no catálogo',data.trending,{link:'catalog?sort=popular'})}${rail('updates','Novos capítulos','Obras com capítulos atualizados no catálogo',data.updates,{link:'catalog?sort=updated'})}${rail('top','Mais bem avaliados','Histórias para entrar na sua próxima maratona',data.top,{ranking:true,link:'catalog?sort=rating'})}${rail('manhwa','Mundos em manhwa','Da Coreia, infinitas possibilidades',data.manhwa,{link:'catalog?kind=manhwa'})}${rail('manhua','Histórias em manhua','Cultivo, fantasia e outros universos',data.manhua,{link:'catalog?kind=manhua'})}${rail('novels','Entre palavras e universos','Uma página pode mudar tudo',data.novels,{link:'catalog?kind=novel'})}${rail('recent','Novas descobertas','Adicionados recentemente ao catálogo',data.recent,{link:'catalog?sort=new'})}${rail('originals','Do estúdio Mahuwa Dragon','Histórias originais, criadas para este universo',data.originals,{link:'catalog?kind=original'})}${data.partial?'<div class="notice">Parte do catálogo está indisponível agora. As obras já carregadas continuam acessíveis. <button class="text-link" data-retry="home">Atualizar catálogo</button></div>':''}</div>`;}
function loadingHome(){return `<section class="skeleton-hero"><div class="hero-inner"><span class="eyebrow">MAHUWA DRAGON</span><h1>Um novo universo.<br>A cada capítulo.</h1><p>Encontrando histórias para sua próxima leitura…</p>${workProgress('Carregando catálogo')}</div></section><div class="home-sections"><div class="section-head"><h2>Explore novas histórias</h2><span class="muted">Carregando catálogo…</span></div>${skeleton()}</div>`;}
async function loadHome(version){try{const data=await api('/api/catalog/home');state.home=data;remember(['featured','trending','popular','recent','updates','top','manhwa','manhua','novels','originals'].flatMap(key=>data[key]||[]));if(version===renderVersion){$('#page-content').innerHTML=homeMarkup();bindShell();}}catch(error){if(version===renderVersion)$('#page-content').innerHTML=`<div class="page-wrap error-state">${empty('O catálogo deu uma pausa.',error.message,'<div class="actions"><button class="btn primary" data-retry="home">Tentar novamente</button><a class="btn" href="#/import">Ler meus arquivos</a></div>')}</div>`;}}
function catalogMarkup(params){const selected=params.get('kind')||'',sort=params.get('sort')||'popular',q=params.get('q')||'';return `<div class="page-wrap">${heading(q?'Sua próxima descoberta.':selected?`${kindNames[selected]||'Histórias'} para explorar.`:'Histórias sem fronteiras.',q?`Resultados para “${q}”`:'Escolha um universo. Encontre uma história.')}<form class="catalog-search" id="catalog-search" role="search">${icon('search')}<label class="sr-only" for="catalog-query">Buscar no catálogo</label><input id="catalog-query" type="search" maxlength="150" placeholder="Título, autor ou palavra-chave" value="${esc(q)}"><button class="btn small primary">Buscar</button></form><div class="catalog-toolbar"><div class="filters">${[['popular','Em alta'],['rating','Bem avaliados'],['updated','Atualizações'],['new','Novidades']].map(([value,label])=>`<button class="filter${sort===value?' active':''}" data-sort="${value}">${label}</button>`).join('')}</div><div class="catalog-selects"><label>Formato<select class="select-control" id="kind-select"><option value="">Todos</option>${Object.entries(kindNames).map(([value,label])=>`<option value="${value}"${value===selected?' selected':''}>${label}</option>`).join('')}</select></label><label>Capítulos<select class="select-control" id="origin-select"><option value="">Todos os idiomas</option>${[['ja','Japonês'],['ko','Coreano'],['zh','Chinês'],['en','Inglês'],['pt-br','Português (Brasil)']].map(([value,label])=>`<option value="${value}"${params.get('language')===value?' selected':''}>${label}</option>`).join('')}</select></label></div></div><div id="catalog-results">${workProgress('Buscando histórias no catálogo')}${skeleton()}</div></div>`;}
function updateCatalogParam(key,value){const params=route().params;value?params.set(key,value):params.delete(key);params.delete('page');nav('catalog?'+params);}
async function loadCatalog(params,version){
  $('#catalog-search').onsubmit=event=>{event.preventDefault();updateCatalogParam('q',$('#catalog-query').value.trim());};
  $('#kind-select').onchange=event=>updateCatalogParam('kind',event.target.value);$('#origin-select').onchange=event=>updateCatalogParam('language',event.target.value);
  try{const data=await api('/api/catalog/discover?'+params);if(version!==renderVersion)return;remember(data.items);const pages=Math.max(Number(data.page)||1,Number(data.totalPages)||1);$('#catalog-results').innerHTML=(data.items?.length?`<div class="catalog-grid">${data.items.map(item=>mediaCard(item)).join('')}</div>`:empty('Nenhuma história por aqui.','Tente outro título ou altere os filtros.'))+`<nav class="pagination" aria-label="Páginas do catálogo"><button class="btn ghost small" data-catalog-page="${Math.max(1,(data.page||1)-1)}"${data.page<=1?' disabled':''}>${icon('back')} Anterior</button><span>Página ${data.page||1}${data.totalPages?` de ${pages}`:''}</span><button class="btn ghost small" data-catalog-page="${(data.page||1)+1}"${!(data.hasMore||(data.page<pages))?' disabled':''}>Próxima ${icon('next')}</button></nav>`;bindShell();}catch(error){if(version===renderVersion)$('#catalog-results').innerHTML=empty('Não foi possível carregar.',error.message,'<button class="btn primary" data-retry="catalog">Tentar novamente</button>');}
}
function hasSaved(id,kind){return state.library.some(entry=>entry.mediaId===String(id)&&entry.kind===kind);}
function libraryMarkup(params){const kind=params.get('kind')||'all';let entries=kind==='progress'?state.progress.map(entry=>({...entry,kind:'progress'})):state.library.filter(entry=>kind==='all'||entry.kind===kind);const seen=new Set();entries=entries.filter(entry=>{if(kind==='all'&&seen.has(entry.mediaId))return false;seen.add(entry.mediaId);return true;});return `<div class="page-wrap">${heading('Sua coleção. Seu universo.','Organize cada história, do primeiro encontro ao último capítulo.')}${badgeScope()}${!state.user?'<div class="notice">Sua biblioteca e seu progresso são salvos neste navegador. <button class="text-link" data-auth="login">Entre para sincronizar sua conta.</button></div>':''}${state.user&&state.library.some(isImported)?'<div class="notice">Arquivos importados e seu progresso permanecem neste dispositivo.</div>':''}${state.personalError?`<div class="notice">${esc(state.personalError)} <button class="text-link" data-sync>Atualizar</button></div>`:''}<nav class="tabs section" aria-label="Biblioteca">${[['all','Tudo'],...Object.entries(collectionNames),['progress','Continuar lendo']].map(([value,label])=>`<a class="${value===kind?'active':''}" href="#/library?kind=${value}">${label}</a>`).join('')}</nav><div id="library-results">${entries.length?`<div class="catalog-grid">${entries.map(entry=>{const item=entry.item||state.items.get(entry.mediaId);if(!item)return '';return `<div class="collection-card">${mediaCard(item)}${readingProgress(entry)}${entry.kind!=='progress'?`<button class="collection-remove" data-remove-id="${esc(entry.mediaId)}" data-remove-kind="${esc(entry.kind)}" aria-label="Remover ${esc(item.title)} da lista">${icon('close')}</button>`:''}${entry.kind==='progress'?`<a class="text-link" href="${readLink(entry.chapterId)}">Continuar leitura →</a>`:`<small class="muted">${esc(collectionNames[entry.kind]||'Na sua lista')}${isImported(entry)?' · Neste dispositivo':''}</small>`}</div>`;}).join('')}</div>`:empty('Espaço para suas próximas histórias.','Salve uma obra no catálogo ou comece a ler um capítulo para vê-la aqui.','<a href="#/catalog" class="btn primary">Explorar catálogo</a>')}</div></div>`;}
async function toggleSaved(mediaId,kind,removeExplicit=false){const item=state.items.get(String(mediaId))||state.detail;if(!item)return;const remove=removeExplicit||hasSaved(mediaId,kind);const buttons=$$('[data-save-id]').filter(button=>button.dataset.saveId===String(mediaId));buttons.forEach(button=>button.disabled=true);try{if(state.user&&!isImported(mediaId))await post('/api/library',{mediaId:String(mediaId),kind,remove,item});let entries=state.library.filter(entry=>!(entry.mediaId===String(mediaId)&&entry.kind===kind));if(!remove){if(['reading','completed','paused','dropped'].includes(kind))entries=entries.filter(entry=>entry.mediaId!==String(mediaId)||!['reading','completed','paused','dropped'].includes(entry.kind));entries.unshift({mediaId:String(mediaId),kind,item,updatedAt:Date.now()});}state.library=entries;persistCollections();toast(remove?'Removido da sua biblioteca.':`Salvo em ${collectionNames[kind]||'sua biblioteca'}. ${isImported(mediaId)?'Neste dispositivo':collectionScope()}.`);if(['library','home'].includes(route().page))render();else updateSaveButtons();}catch(error){toast(error.message,true);}finally{buttons.forEach(button=>button.disabled=false);}}
function updateSaveButtons(){for(const button of $$('[data-save-id]')){const enabled=hasSaved(button.dataset.saveId,button.dataset.saveKind);button.classList.toggle('selected',enabled);button.setAttribute('aria-pressed',String(enabled));const kind=button.dataset.saveKind;button.innerHTML=icon(enabled?'check':kind==='favorite'?'heart':'plus')+(kind==='favorite'?(enabled?'Favoritado':'Favoritar'):(enabled?'Na sua lista':'Ler depois'));}}
async function loadPersonal(){if(!state.user)return;state.personalError='';const userId=state.user.id;try{const [library,progress]=await Promise.all([api('/api/library'),api('/api/progress')]);if(state.user?.id!==userId)return;state.library=[...(library.items||[]).filter(entry=>!isImported(entry)),...store.get('library_imports',[])];state.progress=[...(progress.items||library.progress||[]).filter(entry=>!isImported(entry)),...store.get('progress_imports',[])];remember(state.library.map(entry=>entry.item).filter(Boolean));remember(state.progress.map(entry=>entry.item).filter(Boolean));persistCollections();if(['home','library','profile'].includes(route().page))render();else updateSaveButtons();}catch(error){state.personalError='Não foi possível sincronizar sua biblioteca agora.';if(route().page==='library')render();}}
function detailMarkup(item,recommendations=[]){const id=identity();const reading=state.library.find(entry=>entry.mediaId===item.id&&['reading','completed','paused','dropped'].includes(entry.kind));return `<section class="detail-banner"><img class="detail-art" src="${esc(safeUrl(item.backdropUrl||item.coverUrl,'/assets/dragon-art.webp'))}" alt=""><div class="detail-banner-content"><a class="page-back" href="#/catalog">${icon('back')} Catálogo</a><div class="detail-meta"><span class="badge accent">${kindNames[item.kind]||'Mangá'}</span>${Number(item.rating)>0?`<span class="score">★ ${Number(item.rating).toFixed(1)}</span>`:''}<span>${esc(statusName(item.status))}</span>${item.year?`<span>${esc(item.year)}</span>`:''}</div><h1>${esc(item.title)}</h1>${item.originalTitle&&item.originalTitle!==item.title?`<p class="detail-original">${esc(item.originalTitle)}</p>`:''}</div></section><div class="detail-layout"><aside class="detail-side"><img class="detail-cover" src="${esc(safeUrl(item.coverUrl))}" alt="Capa de ${esc(item.title)}"><div class="actions"><button class="btn primary" data-start-reading>${icon('book')} Ler agora</button><button class="btn" data-save-id="${esc(item.id)}" data-save-kind="favorite" aria-pressed="${hasSaved(item.id,'favorite')}">${icon(hasSaved(item.id,'favorite')?'check':'heart')}${hasSaved(item.id,'favorite')?'Favoritado':'Favoritar'}</button><button class="btn" data-save-id="${esc(item.id)}" data-save-kind="later" aria-pressed="${hasSaved(item.id,'later')}">${icon(hasSaved(item.id,'later')?'check':'plus')}${hasSaved(item.id,'later')?'Na sua lista':'Ler depois'}</button><label class="sr-only" for="reading-status">Status de leitura</label><select id="reading-status" class="select-control"><option value="">Status de leitura</option>${['reading','completed','paused','dropped'].map(kind=>`<option value="${kind}"${reading?.kind===kind?' selected':''}>${collectionNames[kind]}</option>`).join('')}</select><button class="btn ghost" data-share>${icon('share')} Compartilhar</button></div><div class="metadata-list"><div><b>Autores</b><span>${esc(item.authors?.join(', ')||'Não informado')}</span></div><div><b>Origem</b><span>${esc(item.originLanguage?.toUpperCase()||'Não informada')}</span></div><div><b>Catálogo</b><span>${esc(item.provider==='local'?'Original Mahuwa Dragon':item.provider||'Externo')}</span></div>${item.chapterCount?`<div><b>Capítulos listados</b><span>${Number(item.chapterCount)}</span></div>`:''}</div></aside><article class="detail-body"><p class="detail-description">${esc(item.description||'Esta obra ainda não tem uma sinopse disponível.')}</p><div class="detail-tags">${(item.tags||[]).map((tag,index)=>`<a href="#/catalog?tag=${encodeURIComponent(item.tagIds?.[index]||(typeof tag==='string'?tag:tag.id||tag.name))}">${esc(typeof tag==='string'?tag:tag.name)}</a>`).join('')}</div><div class="detail-tabs" role="tablist" aria-label="Sobre a obra"><button data-detail-tab="chapters" role="tab" aria-selected="true" aria-controls="detail-chapters">Capítulos</button><button data-detail-tab="comments" role="tab" aria-selected="false" aria-controls="detail-comments">Comunidade</button><button data-detail-tab="recommendations" role="tab" aria-selected="false" aria-controls="detail-recommendations">Mais histórias</button></div><section id="detail-chapters" role="tabpanel"><div class="chapters-toolbar"><div class="field"><label for="chapter-language">Idioma dos capítulos</label><select id="chapter-language"><option value="pt-br">Português (Brasil)</option><option value="all">Todos · tradução automática</option></select></div><button class="btn small ghost" data-chapter-order="desc">Mais recentes primeiro ${icon('next')}</button></div><div id="chapters-results" aria-live="polite">${workProgress('Buscando capítulos')}</div></section><section id="detail-comments" role="tabpanel" hidden><div id="discussion"><p class="muted">Carregando comunidade…</p></div></section><section id="detail-recommendations" class="recommendations" role="tabpanel" hidden>${recommendations.length?`<div class="catalog-grid">${recommendations.map(item=>mediaCard(item)).join('')}</div>`:empty('Mais histórias estão a caminho.','Explore o catálogo para encontrar outras obras.','<a href="#/catalog" class="btn">Explorar catálogo</a>')}</section></article></div>`;}
async function loadTitle(id,version){try{let result;if(id.startsWith('import:')){const book=await getImportedBook(id);if(!book)throw new Error('Este arquivo importado não está disponível neste dispositivo.');result={item:book.media,recommendations:[]};}else result=await api('/api/catalog/'+encodeURIComponent(id));if(version!==renderVersion)return;state.detail=result.item;remember([result.item,...(result.recommendations||[])]);$('#page-content').innerHTML=detailMarkup(result.item,result.recommendations||[]);$('#reading-status').onchange=event=>{if(event.target.value)toggleSaved(result.item.id,event.target.value);};$('#chapter-language').onchange=()=>loadChapters(result.item.id,version);bindShell();loadChapters(result.item.id,version);loadComments(result.item.id,version);}catch(error){if(version===renderVersion)$('#page-content').innerHTML=`<div class="page-wrap error-state">${empty('Esta história não abriu.',error.message,'<button class="btn primary" data-retry="title">Tentar novamente</button>')}</div>`;}}
async function loadChapters(id,version,page=1,order){const request=++chaptersVersion;const language=$('#chapter-language')?.value||'pt-br',sort=order||$('[data-chapter-order]')?.dataset.chapterOrder||'desc';$('#chapters-results').innerHTML=workProgress('Buscando capítulos');try{let data;if(id.startsWith('import:')){const book=await getImportedBook(id);data={chapters:[book.chapter],page:1,totalPages:1};}else data=await api(`/api/catalog/${encodeURIComponent(id)}/chapters?`+new URLSearchParams({language,page,order:sort}));if(version!==renderVersion||request!==chaptersVersion)return;$('#chapters-results').innerHTML=data.chapters?.length?`<div class="chapter-list">${data.chapters.map(chapter=>`<a class="chapter-row" href="${readLink(chapter.id)}"><span class="chapter-number">${esc(chapter.number??'•')}</span><span class="chapter-copy"><b>${esc(chapter.title||`Capítulo ${chapter.number??''}`)}</b><small>${esc(chapter.group||'')}${chapter.publishedAt?`${chapter.group?' · ':''}${dateLabel(chapter.publishedAt)}`:''}</small></span><span class="chapter-language">${esc(chapter.language||'')}</span>${icon('next')}</a>`).join('')}</div>${data.hasMore||data.page>1?`<nav class="pagination"><button class="btn small" data-chapter-page="${Math.max(1,data.page-1)}"${data.page<=1?' disabled':''}>Anterior</button><span>Página ${data.page}${data.totalPages?` de ${data.totalPages}`:''}</span><button class="btn small" data-chapter-page="${data.page+1}"${!data.hasMore?' disabled':''}>Próxima</button></nav>`:''}`:empty(language==='pt-br'?'Sem capítulos em português neste catálogo.':'Nenhum capítulo disponível aqui.',language==='pt-br'?'Confira os outros idiomas. O leitor pode traduzir as falas para português.':'A obra pode estar disponível apenas no site de origem.',language==='pt-br'?'<button class="btn primary" data-all-chapters>Ver todos os idiomas</button>':state.detail.url?`<a class="btn" href="${esc(safeUrl(state.detail.url,'https://mangadex.org'))}" target="_blank" rel="noopener noreferrer">Visitar origem ↗</a>`:'');}catch(error){if(version===renderVersion&&request===chaptersVersion)$('#chapters-results').innerHTML=empty('Capítulos indisponíveis.',error.message,'<button class="btn" data-retry="chapters">Tentar novamente</button>');}}
async function startReading(){const item=state.detail;if(!item)return;const progress=state.progress.find(entry=>entry.mediaId===item.id&&entry.chapterId);if(progress){location.hash=readLink(progress.chapterId);return;}if(item.id.startsWith('import:')){const book=await getImportedBook(item.id);location.hash=readLink(book.chapter.id);return;}const button=$('[data-start-reading]');button.disabled=true;try{let data=await api(`/api/catalog/${encodeURIComponent(item.id)}/chapters?language=pt-br&order=asc&page=1`);if(!data.chapters?.length){data=await api(`/api/catalog/${encodeURIComponent(item.id)}/chapters?language=all&order=asc&page=1`);if(data.chapters?.length)toast('Abrindo um capítulo em outro idioma. A tradução pode ser ativada no leitor.');}if(!data.chapters?.length)throw new Error('Esta obra ainda não tem capítulos disponíveis neste catálogo.');location.hash=readLink(data.chapters[0].id);}catch(error){toast(error.message,true);}finally{if(button.isConnected)button.disabled=false;}}
async function openReader(id,version){try{let data;if(id.startsWith('import:')){const book=await getImportedBook(id);if(!book)throw new Error('Importe novamente este arquivo para abri-lo.');data={media:book.media,chapter:book.chapter,pages:book.pages,previousId:null,nextId:null};}else data=await api('/api/chapters/'+encodeURIComponent(id)+'?quality='+(state.prefs.economy?'lite':'original'));if(version!==renderVersion)return;remember([data.media]);const container=$('#reader-container');container.replaceChildren();if(data.externalUrl||data.chapter?.externalUrl){container.innerHTML=`<div class="reader-back-row">${backButton()}</div>`+empty('Este capítulo está na publicação de origem.','A leitura é disponibilizada pelo site do publicador.',`<div class="actions"><a class="btn primary" href="${esc(safeUrl(data.externalUrl||data.chapter.externalUrl,'https://mangadex.org'))}" target="_blank" rel="noopener noreferrer">Abrir capítulo na origem ↗</a><a class="btn" href="${titleLink(data.media?.id||data.chapter.mediaId)}">Voltar à obra</a></div>`);return;}reader=mountReader(container,{...data,api,initialPage:Number(state.progress.find(progress=>progress.chapterId===id)?.page)||0,onNavigate:chapterId=>{location.hash=readLink(chapterId);},onClose:()=>{location.hash=titleLink(data.media.id);},onProgress:progress=>saveProgress({...progress,item:data.media})});document.title=`${data.media.title} · Capítulo ${data.chapter.number??''} · Mahuwa Dragon`;}catch(error){if(version===renderVersion)$('#reader-container').innerHTML=`<div class="reader-back-row">${backButton()}</div>`+empty('A leitura não começou.',error.message,`<div class="actions"><button class="btn primary" data-retry="read">Tentar novamente</button><a class="btn" href="#/catalog">Voltar ao catálogo</a></div>`);}}
function saveProgress(value){const progress={...value,updatedAt:Date.now()};state.progress=[progress,...state.progress.filter(entry=>entry.mediaId!==progress.mediaId)].slice(0,100);persistCollections();if(!state.user||isImported(progress))return;pendingProgress=progress;clearTimeout(progressTimer);const wait=Math.max(0,4000-(Date.now()-lastProgressSave));progressTimer=setTimeout(flushProgress,wait);}
async function flushProgress(){if(!pendingProgress||!state.user)return;const progress=pendingProgress;pendingProgress=null;lastProgressSave=Date.now();try{await post('/api/progress',progress);syncWarning=false;}catch{if(!syncWarning){toast('O progresso ficou neste dispositivo. Não foi possível sincronizá-lo agora.',true);syncWarning=true;}}}
function discussionMarkup(){return `<h2 class="detail-section-title">Cada história abre uma conversa.</h2>${state.user?`<form id="comment-form" class="discussion-form"><label class="sr-only" for="comment-body">Seu comentário</label><textarea id="comment-body" maxlength="3000" required placeholder="O que você achou desta história?"></textarea><div class="discussion-actions"><label class="spoiler-check"><input type="checkbox" id="comment-spoiler"> Contém spoiler</label><button class="btn primary small" type="submit">Publicar comentário</button></div><p class="form-error" id="comment-error" role="alert"></p></form>`:'<div class="notice"><button class="text-link" data-auth="login">Entre na sua conta</button> para participar da conversa.</div>'}<div class="comments section">${state.comments.length?state.comments.map(comment=>`<article class="comment">${avatar(comment.user)}<div class="comment-content"><div class="comment-meta"><a class="${nameClass(comment.user.nameColor)}" href="#/profile/${encodeURIComponent(comment.user.id)}">${esc(comment.user.name)}</a><time datetime="${esc(comment.createdAt)}">${esc(dateLabel(comment.createdAt))}</time></div>${comment.spoiler?`<button class="comment-spoiler" data-spoiler="${esc(comment.id)}">Este comentário contém spoiler. Mostrar.</button><p class="comment-body" id="spoiler-${esc(comment.id)}" hidden>${esc(comment.body)}</p>`:`<p class="comment-body">${esc(comment.body)}</p>`}<div class="comment-tools"><button class="${comment.likedByMe?'liked':''}" data-comment-like="${esc(comment.id)}" aria-pressed="${!!comment.likedByMe}" aria-label="Curtir comentário">${icon('like')}${Number(comment.likes)||0}</button>${state.user?.id===comment.user.id?`<button data-comment-delete="${esc(comment.id)}">Excluir</button>`:''}</div></div></article>`).join(''):'<p class="muted">Ainda não há comentários. Comece esta conversa.</p>'}</div>`;}
async function loadComments(id,version){if(isImported(id)){if($('#discussion'))$('#discussion').innerHTML='<div class="notice">Este arquivo é uma leitura pessoal neste dispositivo. A comunidade fica disponível nas obras do catálogo.</div>';return;}try{const data=await api('/api/comments?mediaId='+encodeURIComponent(id));if(version!==renderVersion||!$('#discussion'))return;state.comments=data.items||[];$('#discussion').innerHTML=discussionMarkup();const form=$('#comment-form');if(form)form.onsubmit=async event=>{event.preventDefault();const button=$('button[type=submit]',form);button.disabled=true;$('#comment-error').textContent='';try{await post('/api/comments',{mediaId:id,body:$('#comment-body').value.trim(),spoiler:$('#comment-spoiler').checked});await loadComments(id,version);}catch(error){$('#comment-error').textContent=error.message;}finally{if(button.isConnected)button.disabled=false;}};}catch(error){if(version===renderVersion&&$('#discussion'))$('#discussion').innerHTML=empty('A conversa está indisponível.',error.message,'<button class="btn small" data-retry="comments">Tentar novamente</button>');}}
function profileMarkup(){
  if(!state.user)return `<div class="page-wrap">${heading('Seu perfil. Sua identidade.','Escolha seu GIF ou foto, crie sua assinatura e leve sua biblioteca com você.')}${empty('Faça parte do Mahuwa Dragon.','Entre ou crie uma conta para personalizar seu perfil e sincronizar suas histórias.','<div class="actions"><button class="btn primary" data-auth="login">Entrar</button><button class="btn" data-auth="register">Criar conta</button></div>')}</div>`;
  const user=state.user,look=identity(user),frame=user.avatarFrame||{x:50,y:50,zoom:100},giphyReady=state.config?.profile?.giphy;
  return `<div class="page-wrap profile-page">${heading('Meu universo.','Personalize seu perfil de um jeito simples. Tudo muda na prévia enquanto você escolhe.')}<div class="profile-grid profile-grid-polished"><aside class="profile-cover cover-${look.cover}" id="profile-preview">${avatar(user,'big-avatar')}<div class="identity-title" id="profile-title-preview">${esc(look.title)}</div><h2 id="profile-name-preview" class="${nameClass(user.nameColor)}">${esc(user.name)}</h2><p id="profile-bio-preview">${esc(user.bio||'A próxima aventura começa na próxima página.')}</p><div class="profile-stats"><div><strong>${state.library.filter(entry=>entry.kind==='favorite').length}</strong><span>Favoritos</span></div><div><strong>${state.library.filter(entry=>entry.kind==='reading').length}</strong><span>Lendo</span></div><div><strong>${state.library.filter(entry=>entry.kind==='completed').length}</strong><span>Concluídos</span></div></div><a class="btn primary profile-giphy-main" href="#/gifs">Escolher GIF no GIPHY</a><form class="profile-privacy" id="privacy-form"><label for="profile-visibility">Quem pode ver meu universo?</label><select id="profile-visibility" class="select-control"><option value="private"${user.visibility!=='public'?' selected':''}>Privado · somente eu</option><option value="public"${user.visibility==='public'?' selected':''}>Público · qualquer pessoa</option></select><p>Seu e-mail nunca aparece para visitantes.</p><button class="btn small" type="submit">Salvar privacidade</button><p class="privacy-message" id="privacy-message" role="status"></p></form><div class="actions"><a class="btn small ghost" href="#/profile/${encodeURIComponent(user.id)}">Ver perfil público ↗</a><button class="btn small ghost" data-logout>Sair</button></div></aside><div class="profile-editor"><section class="panel photo-editor profile-card profile-avatar-card"><div class="profile-section-head"><div><span class="eyebrow">FOTO DO PERFIL</span><h3>Seu avatar, do seu jeito.</h3><p>Use um GIF do GIPHY ou envie JPG, PNG, WebP e GIF. O avatar salvo aparece no cabeçalho, comentários e perfil público.</p></div><div class="profile-service ${giphyReady===true?'is-on':giphyReady===false?'is-off':'is-checking'}"><span></span>${giphyReady===true?'GIPHY conectado':giphyReady===false?'GIPHY indisponível':'Verificando GIPHY'}</div></div><div class="avatar-source-actions"><a class="btn primary" href="#/gifs">Explorar galeria de GIFs</a><label class="btn ghost avatar-file-button" for="avatar-file">Enviar foto ou GIF</label><input id="avatar-file" class="sr-only" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></div><div class="photo-preview-layout profile-photo-workspace"><div><span class="profile-mini-label">Prévia</span><div class="photo-preview"><img id="avatar-preview" src="${esc(safeAvatar(user.avatar))}"${giphyId(user.avatar)?` data-giphy-avatar="${esc(giphyId(user.avatar))}"`:''} style="${frameStyle(frame)}" alt="Prévia do enquadramento do avatar"></div></div><div class="photo-adjustments"><div class="profile-slider"><label for="avatar-x">Posição horizontal</label><input id="avatar-x" type="range" min="0" max="100" value="${Number(frame.x)||50}"></div><div class="profile-slider"><label for="avatar-y">Posição vertical</label><input id="avatar-y" type="range" min="0" max="100" value="${Number(frame.y)||50}"></div><div class="profile-slider"><label for="avatar-zoom">Zoom</label><input id="avatar-zoom" type="range" min="100" max="300" value="${Number(frame.zoom)||100}"></div><button type="button" class="btn ghost small" id="center-photo">Centralizar</button></div></div><div class="actions profile-save-row"><button class="btn primary small" id="save-photo">Salvar foto e ajuste</button><button class="btn ghost small" id="reset-photo">Remover foto</button></div><p class="photo-message" id="photo-message" role="status">Ao clicar em “Usar no meu perfil” no GIPHY, o GIF vira seu avatar em todo o site.</p><div id="photo-progress" hidden></div></section><section class="panel profile-card profile-identity-card"><div class="profile-section-head"><div><span class="eyebrow">IDENTIDADE</span><h3>Nome, bio e visual.</h3><p>Organizado em uma única tela, com prévia instantânea ao lado.</p></div></div><form id="profile-form"><div class="form-grid profile-fields"><div class="field"><label for="profile-name">Nome do perfil</label><input id="profile-name" value="${esc(user.name)}" minlength="1" maxlength="80" required autocomplete="nickname"><small>Emojis e símbolos são aceitos. Até 80 caracteres visíveis.</small></div><div class="field"><label for="profile-email">E-mail da conta</label><input id="profile-email" type="email" value="${esc(user.email||'')}" readonly><small>Somente você vê este e-mail.</small></div><div class="field full"><label for="profile-bio">Sua bio</label><textarea id="profile-bio" maxlength="300" placeholder="Conte um pouco sobre seu universo…">${esc(user.bio||'')}</textarea><small>Até 300 caracteres.</small></div></div><div class="profile-subsection"><div class="profile-subsection-title"><b>Atmosfera do perfil</b><span>Escolha o fundo do seu cartão público.</span></div><input type="hidden" id="profile-cover" value="${look.cover}"><div class="identity-choices">${Object.entries(covers).map(([value,label])=>`<button class="identity-choice" type="button" data-identity-cover="${value}" aria-pressed="${value===look.cover}"><span class="identity-sample cover-${value}"></span><b>${label}</b></button>`).join('')}</div></div><div class="profile-subsection"><div class="profile-subsection-title"><b>Moldura do avatar</b><span>O mesmo estilo acompanha seu GIF ou foto.</span></div><input type="hidden" id="profile-frame" value="${look.frame}"><div class="identity-choices">${Object.entries(frames).map(([value,label])=>`<button class="identity-choice" type="button" data-identity-frame="${value}" aria-pressed="${value===look.frame}"><span class="frame-sample ring-${value}">✦</span><b>${label}</b></button>`).join('')}</div></div><div class="profile-subsection profile-title-color"><div class="field"><label for="profile-title">Seu título pessoal</label><input id="profile-title" value="${esc(look.title)}" minlength="2" maxlength="40"><small>Até 40 caracteres.</small></div><div><label class="profile-label">Cor do seu nome</label><div class="name-preview ${nameClass(user.nameColor)}" id="name-preview">${esc(user.name)}</div><input id="profile-name-color" type="hidden" value="${Object.hasOwn(colors,user.nameColor)?user.nameColor:'ice'}"><div class="name-palette" role="group" aria-label="Cor do nome">${Object.entries(colors).map(([value,label])=>`<button class="name-swatch ${nameClass(value)}" type="button" data-name-color="${value}" aria-label="${label}" aria-pressed="${user.nameColor===value}"><span></span></button>`).join('')}</div></div></div><p class="form-error" id="profile-error" role="alert"></p><div class="profile-save-bar"><span>Confira a prévia antes de salvar.</span><button class="btn primary" type="submit">Salvar alterações</button></div></form></section></div></div></div>`;
}
function bindProfile(){if(!state.user||!$('#profile-form'))return;const userId=state.user.id;const preview=()=>{const cover=$('#profile-cover').value,frame=$('#profile-frame').value,color=$('#profile-name-color').value;$('#profile-preview').className=`profile-cover cover-${cover}`;$('#profile-preview .big-avatar').className=`avatar-frame big-avatar ring-${frame}`;$('#profile-title-preview').textContent=$('#profile-title').value;$('#profile-name-preview').textContent=$('#profile-name').value;$('#profile-name-preview').className=nameClass(color);$('#name-preview').textContent=$('#profile-name').value;$('#name-preview').className='name-preview '+nameClass(color);$('#profile-bio-preview').textContent=$('#profile-bio').value;};
  for(const key of ['name','bio','title'])$('#profile-'+key).oninput=preview;
  for(const kind of ['cover','frame'])$$('[data-identity-'+kind+']').forEach(button=>button.onclick=()=>{const value=button.dataset['identity'+kind[0].toUpperCase()+kind.slice(1)];$('#profile-'+kind).value=value;$$('[data-identity-'+kind+']').forEach(choice=>choice.setAttribute('aria-pressed',String(choice===button)));preview();});
  $$('[data-name-color]').forEach(button=>button.onclick=()=>{$('#profile-name-color').value=button.dataset.nameColor;$$('[data-name-color]').forEach(choice=>choice.setAttribute('aria-pressed',String(choice===button)));preview();});
  $('#profile-form').onsubmit=async event=>{event.preventDefault();const button=$('button[type=submit]',event.currentTarget);button.disabled=true;$('#profile-error').textContent='';try{const data=await post('/api/auth/profile',{name:$('#profile-name').value,bio:$('#profile-bio').value,nameColor:$('#profile-name-color').value,identity:{cover:$('#profile-cover').value,frame:$('#profile-frame').value,title:$('#profile-title').value}});if(state.user?.id!==userId)return;state.user=data.user;toast('Seu perfil foi atualizado.');render();}catch(error){$('#profile-error').textContent=error.message;}finally{if(button.isConnected)button.disabled=false;}};
  $('#privacy-form').onsubmit=async event=>{event.preventDefault();const button=$('button',event.currentTarget);button.disabled=true;try{const data=await post('/api/auth/privacy',{visibility:$('#profile-visibility').value});if(state.user?.id!==userId)return;state.user=data.user;$('#privacy-message').textContent=data.user.visibility==='public'?'Seu perfil está público.':'Seu perfil está privado.';}catch(error){$('#privacy-message').textContent=error.message;}finally{button.disabled=false;}};
  bindPhoto(userId);
}
function bindPhoto(userId){const input=$('#avatar-file'),preview=$('#avatar-preview'),message=$('#photo-message');let file=null;const readFrame=()=>({x:Number($('#avatar-x').value),y:Number($('#avatar-y').value),zoom:Number($('#avatar-zoom').value)});const update=()=>preview.style.cssText=frameStyle(readFrame());for(const field of ['x','y','zoom'])$('#avatar-'+field).oninput=update;$('#center-photo').onclick=()=>{$('#avatar-x').value=50;$('#avatar-y').value=50;$('#avatar-zoom').value=100;update();};
  input.onchange=async()=>{const chosen=input.files?.[0];if(!chosen)return;try{validateAvatarFile(chosen);}catch(error){message.textContent=error.message;input.value='';return;}const url=URL.createObjectURL(chosen),image=new Image();image.src=url;try{await image.decode();if(!input.isConnected){URL.revokeObjectURL(url);return;}if(image.naturalWidth>8192||image.naturalHeight>8192)throw new Error('A imagem precisa ter até 8.192 pixels em cada dimensão.');if(avatarObjectUrl)URL.revokeObjectURL(avatarObjectUrl);avatarObjectUrl=url;file=chosen;preview.removeAttribute('data-giphy-avatar');preview.removeAttribute('data-giphy-resolving');preview.src=url;$('#center-photo').click();message.textContent='Prévia pronta. Ajuste o enquadramento e salve.';}catch(error){URL.revokeObjectURL(url);message.textContent=error.message;}};
  const accept=data=>{state.user={...state.user,avatar:data.avatar,avatarFrame:data.avatarFrame};if(avatarObjectUrl){URL.revokeObjectURL(avatarObjectUrl);avatarObjectUrl=null;}file=null;input.value='';const gif=giphyId(data.avatar),src=safeAvatar(data.avatar);for(const img of [preview,$('#profile-preview img')].filter(Boolean)){img.src=src;img.removeAttribute('data-giphy-resolving');if(gif)img.dataset.giphyAvatar=gif;else img.removeAttribute('data-giphy-avatar');img.style.cssText=frameStyle(data.avatarFrame);}giphyAvatars.refresh();updateAccount();};
  $('#save-photo').onclick=async event=>{const button=event.currentTarget,controller=new AbortController();avatarUploadController=controller;button.disabled=true;input.disabled=true;message.textContent='Salvando foto…';photoProgress(file?'Enviando foto':'Salvando enquadramento');try{const frame=readFrame();const data=file?await uploadAvatar(file,frame,{signal:controller.signal,onProgress:progress=>{if(!input.isConnected||controller.signal.aborted)return;if(progress.phase==='saving'){photoProgress('Confirmando salvamento');message.textContent='Upload enviado. Confirmando o salvamento…';}else{photoProgress('Enviando foto',progress.percent);message.textContent=progress.total?`${(progress.loaded/1048576).toFixed(1)} MB de ${(progress.total/1048576).toFixed(1)} MB enviados.`:'Enviando o arquivo original…';}}}):await post('/api/profile/avatar/crop?'+new URLSearchParams(frame),{});if(state.user?.id!==userId||controller.signal.aborted||!input.isConnected)return;accept(data);message.textContent='Foto e enquadramento salvos.';}catch(error){if(input.isConnected)message.textContent=error.name==='AbortError'?'Envio cancelado.':error.message;}finally{if(button.isConnected){button.disabled=false;input.disabled=false;photoProgress();}if(avatarUploadController===controller)avatarUploadController=null;}};
  $('#reset-photo').onclick=async event=>{const button=event.currentTarget;button.disabled=true;photoProgress('Removendo foto');try{const data=await post('/api/profile/avatar/reset',{});if(state.user?.id!==userId)return;accept(data);$('#center-photo').click();message.textContent='Avatar removido. Escolha um GIF no GIPHY ou envie sua imagem.';}catch(error){message.textContent=error.message;}finally{if(button.isConnected){button.disabled=false;photoProgress();}}};
}
async function loadPublicProfile(id,version){try{const data=await api('/api/profiles/'+encodeURIComponent(id));if(version!==renderVersion)return;const user=data.user||data.profile;const look=identity(user),entries=data.library||[],stats=data.stats||{};remember(entries.map(entry=>entry.item).filter(Boolean));$('#page-content').innerHTML=`<div class="page-wrap"><section class="public-profile cover-${look.cover}">${avatar(user,'big-avatar')}<div><span class="eyebrow">UNIVERSO DE LEITURA · ${user.visibility==='public'?'PÚBLICO':'PRIVADO'}</span><span class="identity-title">${esc(look.title)}</span><h1 class="${nameClass(user.nameColor)}">${esc(user.name)}</h1><p>${esc(user.bio||'')}</p>${data.private?'':`<div class="public-profile-stats"><span><strong>${Number(stats.favorites)||0}</strong> favoritos</span><span><strong>${Number(stats.reading)||0}</strong> lendo</span><span><strong>${Number(stats.completed)||0}</strong> concluídos</span><span><strong>${Number(stats.chaptersRead)||0}</strong> capítulos lidos</span></div>`}<div class="actions">${state.user?.id===user.id?'<a class="btn small" href="#/profile">Editar meu perfil</a>':''}<button class="btn ghost small" data-copy-profile>Copiar link do perfil</button></div></div></section>${data.private||user.visibility!=='public'&&state.user?.id!==user.id?empty('Este universo é privado.','O leitor escolheu manter sua biblioteca para si.'):entries.length?`<div class="section-head"><h2>Biblioteca deste universo</h2></div><div class="catalog-grid">${[...new Map(entries.filter(entry=>entry.item).map(entry=>[entry.mediaId,entry.item])).values()].map(item=>mediaCard(item)).join('')}</div>`:empty('Este universo ainda está começando.','A biblioteca pública ainda não tem histórias.')}</div>`;bindShell();}catch(error){if(version===renderVersion)$('#page-content').innerHTML=`<div class="page-wrap">${empty('Perfil indisponível.',error.message,'<a class="btn" href="#/">Voltar ao início</a>')}</div>`;}}
function settingsMarkup(){return `<div class="page-wrap">${heading('Do seu jeito.','Ajuste o ambiente da sua leitura. As opções de tradução ficam dentro do leitor.')}<section class="panel settings-card">${[['motion','Animações da interface','Transições suaves e efeitos do catálogo.'],['economy','Economizar dados','Prefira a qualidade leve nas imagens dos capítulos.']].map(([key,title,description])=>`<div class="setting-row"><div><b>${title}</b><p>${description}</p></div><button class="switch" data-pref="${key}" role="switch" aria-checked="${!!state.prefs[key]}" aria-label="${title}"></button></div>`).join('')}<div class="divider"></div><p class="muted">As preferências ficam neste navegador${state.user?' e são sincronizadas com sua conta quando salvas':''}.</p><div class="notice"><strong>Tradução de imagens:</strong> o OCR local reconhece a imagem no navegador e envia o texto ao serviço de tradução. Gemini envia a imagem para reconhecimento e tradução quando estiver habilitado. Você escolhe o modo no leitor.</div>${state.config?`<p class="muted section">${state.config.translation?.gemini?'Gemini disponível para contas conectadas, sujeito a cotas.':'Tradução básica disponível por melhor esforço. Gemini não está habilitado neste servidor.'}</p>`:''}</section></div>`;}
function openAccount(mode='login'){if(state.user){nav('profile');return;}if(dialog)closeAccount();lastFocus=document.activeElement;const login=mode==='login';const modal=document.createElement('div');modal.className='modal-back';modal.innerHTML=`<section class="modal auth-dialog" role="dialog" aria-modal="true" aria-labelledby="auth-title"><button class="icon-btn modal-close" data-close-auth aria-label="Fechar">${icon('close')}</button><div class="auth-art"><img src="/assets/dragon-mark.webp" alt=""><strong>Mahuwa<span>Dragon</span></strong></div><span class="eyebrow">SEU UNIVERSO ACOMPANHA VOCÊ</span><h2 id="auth-title">${login?'Que bom ter você de volta.':'Sua próxima história começa aqui.'}</h2><p>${login?'Entre para continuar sua leitura e encontrar sua coleção.':'Crie uma conta para salvar suas histórias e personalizar seu perfil.'}</p><form id="auth-form">${login?'':'<div class="field"><label for="auth-name">Nome de usuário</label><input id="auth-name" autocomplete="nickname" minlength="1" maxlength="80" required></div>'}<div class="field"><label for="auth-email">E-mail</label><input id="auth-email" type="email" autocomplete="email" maxlength="254" required></div><div class="field"><label for="auth-password">Senha</label><div class="auth-password"><input id="auth-password" type="password" autocomplete="${login?'current-password':'new-password'}" minlength="${login?1:12}" maxlength="128" required><button type="button" id="reveal-password">Mostrar</button></div>${login?'':'<small>Use pelo menos 12 caracteres.</small>'}</div><p class="form-error" id="auth-error" role="alert"></p><button class="btn primary" id="auth-submit" type="submit">${login?'Entrar na minha conta':'Criar minha conta'}</button></form><div class="modal-switch">${login?'Novo por aqui?':'Já tem uma conta?'} <button class="text-link" data-auth="${login?'register':'login'}">${login?'Criar conta':'Entrar'}</button></div><p class="terms-note">Sua biblioteca é privada por padrão. Você pode escolher o que compartilhar no seu perfil.</p></section>`;
  $('#modal-root').append(modal);dialog=modal;document.body.classList.add('modal-open');
  if(!login&&state.config?.registrationAvailable===false){$('#auth-error').textContent='A criação de contas está indisponível neste servidor no momento.';$('#auth-submit').disabled=true;}
  $('#reveal-password').onclick=event=>{const input=$('#auth-password'),show=input.type==='password';input.type=show?'text':'password';event.target.textContent=show?'Ocultar':'Mostrar';};
  $('#auth-form').onsubmit=async event=>{event.preventDefault();const button=$('#auth-submit');button.disabled=true;$('#auth-error').textContent='';try{const data=await post('/api/auth/'+mode,{email:$('#auth-email').value.trim(),password:$('#auth-password').value,...(!login?{name:$('#auth-name').value.trim(),avatar:'/assets/avatar-default.svg'}:{})});if(!data.user?.id)throw new Error('O servidor não confirmou a sessão.');state.user=data.user;state.authReady=true;clearTimeout(progressTimer);pendingProgress=null;restoreCollections();closeAccount();updateAccount();toast(login?'Bem-vindo de volta.':'Sua conta foi criada. Personalize seu perfil.');await loadPersonal();if(route().page==='profile')render();else if(route().page==='title'&&state.detail)loadComments(state.detail.id,renderVersion);}catch(error){if($('#auth-error'))$('#auth-error').textContent=error.message;}finally{if(button.isConnected)button.disabled=false;}};
  modal.onclick=event=>{if(event.target===modal||event.target.closest('[data-close-auth]'))closeAccount();};modal.onkeydown=event=>{if(event.key==='Escape')closeAccount();if(event.key==='Tab'){const targets=$$('button:not([disabled]),input,a[href]',modal),first=targets[0],last=targets.at(-1);if(event.shiftKey&&document.activeElement===first){last.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===last){first.focus();event.preventDefault();}}};setTimeout(()=>($('#auth-name')||$('#auth-email'))?.focus(),0);
}
function closeAccount(){dialog?.remove();dialog=null;document.body.classList.remove('modal-open');if(lastFocus?.isConnected)lastFocus.focus();}

function importDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('mahuwa-dragon-imports',1);request.onupgradeneeded=()=>{request.result.createObjectStore('books',{keyPath:'id'});request.result.createObjectStore('meta',{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(new Error('O armazenamento de arquivos não está disponível.'));});}
async function persistBook(book){const db=await importDB();try{await new Promise((resolve,reject)=>{const tx=db.transaction(['books','meta'],'readwrite');const {pages,...base}=book;tx.objectStore('books').put({...base,pages:pages.map(({blob,text,index,filename})=>({blob,text,index,filename}))});tx.objectStore('meta').put({id:book.id,media:book.media,chapter:book.chapter,count:book.pages.length});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}finally{db.close();}}
async function getImportedBook(id){if(books.has(id))return books.get(id);try{const db=await importDB();const book=await new Promise((resolve,reject)=>{const request=db.transaction('books').objectStore('books').get(id);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});db.close();if(!book)return null;book.persisted=true;book.pages=book.pages.map(page=>({...page,...(page.blob?{url:URL.createObjectURL(page.blob)}:{})}));books.set(id,book);remember([book.media]);return book;}catch{return null;}}
async function importedList(){try{const db=await importDB();const items=await new Promise((resolve,reject)=>{const request=db.transaction('meta').objectStore('meta').getAll();request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});db.close();return [...new Map([...items,...[...books.values()].map(book=>({id:book.id,media:book.media,chapter:book.chapter,count:book.pages.length}))].map(item=>[item.id,item])).values()];}catch{return [...books.values()].map(book=>({id:book.id,media:book.media,chapter:book.chapter,count:book.pages.length}));}}
function importMarkup(){return `<div class="page-wrap">${heading('Suas páginas. Seu universo.','Abra seus próprios arquivos e use o mesmo leitor, com tradução e revisão de falas.')}<section class="panel import-panel"><div class="drop-zone" id="import-drop">${icon('import')}<h2>Uma história esperando para ser lida.</h2><p>Arraste imagens, um capítulo ZIP/CBZ ou uma novel em TXT/EPUB. Seus arquivos ficam neste dispositivo.</p><div class="actions"><button class="btn primary" id="choose-import">Escolher arquivos</button><button class="btn" id="choose-folder">Abrir pasta</button></div><input id="import-files" type="file" class="sr-only" multiple accept="image/png,image/jpeg,image/webp,image/gif,image/avif,.zip,.cbz,.txt,.epub"><input id="import-folder" type="file" class="sr-only" multiple webkitdirectory accept="image/*"></div><p class="photo-message" id="import-message" role="status">Imagens: até 25 MB por arquivo. ZIP/CBZ: até 200 MB. TXT/EPUB: até 20 MB. Máximo de 300 páginas por importação.</p><div id="import-progress" hidden></div><div class="import-list" id="import-list">${workProgress('Carregando seus arquivos')}</div></section></div>`;}
async function refreshImports(version){const list=await importedList();if(version!==renderVersion||!$('#import-list'))return;$('#import-list').innerHTML=list.length?list.map(item=>`<div class="import-item">${icon(item.media.kind==='novel'?'book':'import')}<div><strong>${esc(item.media.title)}</strong><small>${item.count} ${item.media.kind==='novel'?'seções de texto':'páginas'} · Neste dispositivo</small></div><a class="btn primary small" href="${readLink(item.id)}">Ler agora</a><button class="icon-btn" data-delete-import="${esc(item.id)}" aria-label="Remover ${esc(item.media.title)}">${icon('close')}</button></div>`).join(''):'<p class="muted">Seus capítulos importados aparecerão aqui.</p>';}
function textPages(text){const chunks=[];let current='';for(const paragraph of text.replace(/\r\n/g,'\n').split(/\n\s*\n/)){if(current.length+paragraph.length>10000&&current){chunks.push(current);current='';}if(paragraph.length>20000){if(current){chunks.push(current);current='';}for(let i=0;i<paragraph.length;i+=10000)chunks.push(paragraph.slice(i,i+10000));}else current+=(current?'\n\n':'')+paragraph;}if(current.trim())chunks.push(current);if(chunks.length>300)throw new Error('Esta novel excede 300 seções. Divida o arquivo para importar.');return chunks.map((text,index)=>({text,index,filename:`Seção ${index+1}`}));}
const imageExtension=/\.(png|jpe?g|webp|gif|avif|bmp)$/i;
const naturalSort=(a,b)=>a.localeCompare(b,'pt-BR',{numeric:true,sensitivity:'base'});
function unpack(data,mode='images'){if(!globalThis.fflate)throw new Error('O leitor de arquivos compactados não carregou. Recarregue a página.');let bytes=0,count=0;return fflate.unzipSync(new Uint8Array(data),{filter(entry){const allowed=mode==='epub'?/\.(xml|opf|xhtml|html|htm)$/i.test(entry.name):imageExtension.test(entry.name)&&!entry.name.includes('__MACOSX/');if(!allowed)return false;bytes+=entry.originalSize;count++;if(bytes>200*1024*1024||count>1000||entry.originalSize>25*1024*1024)throw new Error('O arquivo compactado excede os limites de segurança para esta leitura.');return true;}});}
function epubPages(files){const decoder=new TextDecoder(),parser=new DOMParser(),container=files['META-INF/container.xml'];if(!container)throw new Error('O EPUB não contém um índice de conteúdo válido.');const doc=parser.parseFromString(decoder.decode(container),'application/xml');const path=doc.querySelector('rootfile')?.getAttribute('full-path');if(!path||!files[path])throw new Error('Não foi possível encontrar o conteúdo deste EPUB.');const opf=parser.parseFromString(decoder.decode(files[path]),'application/xml'),base=path.substring(0,path.lastIndexOf('/')+1),manifest=new Map([...opf.querySelectorAll('manifest > item')].map(item=>[item.getAttribute('id'),item.getAttribute('href')]));const pages=[];for(const item of opf.querySelectorAll('spine > itemref')){const href=manifest.get(item.getAttribute('idref'));if(!href)continue;const filename=decodeURIComponent(new URL(href,'https://local.invalid/'+base).pathname.slice(1));if(!files[filename])continue;const content=parser.parseFromString(decoder.decode(files[filename]),'text/html');content.querySelectorAll('script,style,noscript,nav').forEach(node=>node.remove());const blocks=[...content.querySelectorAll('h1,h2,h3,p,li,blockquote')].map(node=>node.textContent.trim()).filter(Boolean);const text=blocks.length?blocks.join('\n\n'):content.body.textContent.trim();for(const page of textPages(text))pages.push({...page,index:pages.length,filename:filename.split('/').pop()});if(pages.length>300)throw new Error('Esta novel tem mais de 300 seções. Divida o arquivo para importar.');}if(!pages.length)throw new Error('Este EPUB não contém texto legível ou usa proteção incompatível.');return pages;}
async function importFiles(inputFiles){const createdUrls=[];const files=Array.from(inputFiles);if(!files.length)return;if(importing){toast('Aguarde a importação atual.');return;}importing=true;const message=$('#import-message');const buttons=[$('#choose-import'),$('#choose-folder')];buttons.forEach(button=>button.disabled=true);message.textContent='Abrindo seus arquivos…';importProgress('Abrindo seus arquivos');try{let pages=[],kind='manga',name=files[0].name.replace(/\.[^.]+$/,'');if(files.length===1&&/\.(txt|epub)$/i.test(files[0].name)){if(files[0].size>20*1024*1024)throw new Error('A novel precisa ter até 20 MB.');kind='novel';importProgress('Lendo novel');pages=/\.epub$/i.test(files[0].name)?epubPages(unpack(await files[0].arrayBuffer(),'epub')):textPages(await files[0].text());}else{let images=files;if(files.length===1&&/\.(zip|cbz)$/i.test(files[0].name)){if(files[0].size>200*1024*1024)throw new Error('O ZIP/CBZ precisa ter até 200 MB.');importProgress('Abrindo ZIP/CBZ');const contents=unpack(await files[0].arrayBuffer());images=Object.entries(contents).sort(([a],[b])=>naturalSort(a,b)).map(([name,data])=>new File([data],name.split('/').pop(),{type:({png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',gif:'image/gif',avif:'image/avif',bmp:'image/bmp'})[name.split('.').pop().toLowerCase()]}));}images=images.filter(file=>file.type.startsWith('image/')||imageExtension.test(file.name)).sort((a,b)=>naturalSort(a.webkitRelativePath||a.name,b.webkitRelativePath||b.name));if(images.length>300)throw new Error('Importe até 300 imagens por capítulo.');let total=0;for(const file of images){if(file.size>25*1024*1024)throw new Error(`${file.name} excede 25 MB.`);total+=file.size;if(total>200*1024*1024)throw new Error('As imagens juntas excedem 200 MB.');const url=URL.createObjectURL(file);createdUrls.push(url);pages.push({blob:file,url,index:pages.length,filename:file.name});importProgress(`Preparando páginas · ${pages.length} de ${images.length}`,pages.length/images.length*100);await new Promise(resolve=>setTimeout(resolve,0));}if(files.length>1)name=files[0].webkitRelativePath?.split('/')[0]||'Meu capítulo';}if(!pages.length)throw new Error('Nenhuma imagem ou texto compatível foi encontrado.');const id='import:'+crypto.randomUUID(),media={id,title:name,description:'Conteúdo importado por você, salvo neste dispositivo.',coverUrl:'/assets/poster-placeholder.svg',kind,originLanguage:'auto',provider:'local',status:'completed',tags:[],authors:[],chapterCount:1,available:true};const book={id,media,chapter:{id,mediaId:id,number:1,title:name,language:'auto',kind,pages:pages.length},pages};books.set(id,book);remember([media]);importProgress('Salvando no dispositivo');let saved=true;try{await persistBook(book);book.persisted=true;}catch{saved=false;book.persisted=false;}message.textContent=saved?`${pages.length} ${kind==='novel'?'seções':'páginas'} prontas. O arquivo está salvo neste dispositivo.`:'O arquivo está pronto nesta sessão, mas não pôde ser salvo. Ao recarregar, importe novamente.';importProgress('Importação pronta',100);await refreshImports(renderVersion);toast('Importação pronta. Abra a leitura quando quiser.');}catch(error){createdUrls.forEach(url=>URL.revokeObjectURL(url));message.textContent=error.message;toast(error.message,true);if($('#import-progress'))$('#import-progress').hidden=true;}finally{importing=false;buttons.forEach(button=>{if(button.isConnected)button.disabled=false;});}}
function bindImport(version){$('#choose-import').onclick=()=>$('#import-files').click();$('#choose-folder').onclick=()=>$('#import-folder').click();for(const id of ['import-files','import-folder'])$('#'+id).onchange=async event=>{await importFiles(event.target.files);event.target.value='';};const drop=$('#import-drop');for(const type of ['dragenter','dragover'])drop.addEventListener(type,event=>{event.preventDefault();drop.classList.add('dragover');});for(const type of ['dragleave','drop'])drop.addEventListener(type,event=>{event.preventDefault();drop.classList.remove('dragover');});drop.addEventListener('drop',event=>importFiles(event.dataTransfer.files));refreshImports(version);}
async function deleteImport(id){try{const db=await importDB();await new Promise((resolve,reject)=>{const tx=db.transaction(['books','meta'],'readwrite');tx.objectStore('books').delete(id);tx.objectStore('meta').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();}catch{if(!books.has(id)||books.get(id).persisted){toast('Não foi possível remover este arquivo do armazenamento.',true);return;}}const book=books.get(id);book?.pages.forEach(page=>{if(page.url?.startsWith('blob:'))URL.revokeObjectURL(page.url);});books.delete(id);state.progress=state.progress.filter(entry=>entry.mediaId!==id);state.library=state.library.filter(entry=>entry.mediaId!==id);persistCollections();refreshImports(renderVersion);toast('Arquivo removido deste dispositivo.');}

async function render(){reader?.destroy();reader=null;giphyPageController?.destroy();giphyPageController=null;avatarUploadController?.abort();avatarUploadController=null;if(avatarObjectUrl){URL.revokeObjectURL(avatarObjectUrl);avatarObjectUrl=null;}const version=++renderVersion,current=route();document.title='Mahuwa Dragon';let content;
  if(current.page==='home')content=state.home?homeMarkup():loadingHome();
  else if(current.page==='catalog')content=catalogMarkup(current.params);
  else if(current.page==='title')content=`<div class="page-wrap">${workProgress('Abrindo a obra')}${skeleton()}</div>`;
  else if(current.page==='read')content=`<div id="reader-container"><div class="reader-loading"><div class="reader-back-row">${backButton()}</div><span class="eyebrow">MAHUWA DRAGON</span><h2>Preparando sua leitura…</h2><p>Buscando as páginas deste capítulo.</p>${workProgress('Abrindo capítulo')}</div></div>`;
  else if(current.page==='library')content=libraryMarkup(current.params);
  else if(current.page==='profile')content=current.id?`<div class="page-wrap">${workProgress('Carregando perfil')}${skeleton()}</div>`:profileMarkup();
  else if(current.page==='settings')content=settingsMarkup();
  else if(current.page==='gifs')content=giphyPage();
  else if(current.page==='import')content=importMarkup();
  else {nav('');return;}
  root.innerHTML=layout(content,{home:current.page==='home',reading:current.page==='read'});bindShell();window.scrollTo({top:0,behavior:'instant'});
  if(current.page==='home'&&!state.home)loadHome(version);
  if(current.page==='catalog')loadCatalog(current.params,version);
  if(current.page==='title')loadTitle(current.id,version);
  if(current.page==='read')openReader(current.id,version);
  if(current.page==='profile'){if(current.id)loadPublicProfile(current.id,version);else bindProfile();}
  if(current.page==='gifs')giphyPageController=mountGiphy($('#page-content'),{client:giphyClient,user:()=>state.user,onLogin:()=>openAccount('login'),onSelect:async id=>{const userId=state.user?.id;if(!userId)throw new Error('Entre para personalizar seu perfil.');const frame=state.user.avatarFrame||{x:50,y:50,zoom:100},data=await post('/api/profile/avatar/giphy?'+new URLSearchParams(frame),{id});if(state.user?.id!==userId)throw new Error('Entre novamente para salvar sua escolha.');state.user={...state.user,avatar:data.avatar,avatarFrame:data.avatarFrame};toast('Seu GIF foi salvo no perfil.');nav('profile');}});
  if(current.page==='import')bindImport(version);
}
document.addEventListener('click',async event=>{const button=event.target.closest('button,a');if(!button)return;
  if(button.hasAttribute('data-app-back')){event.preventDefault();goBack();return;}
  if(button.classList.contains('skip-link')){event.preventDefault();$('#page-content')?.focus();return;}
  if(button.dataset.auth){event.preventDefault();openAccount(button.dataset.auth);return;}
  if(button.hasAttribute('data-menu')){const open=$('.site-header').classList.toggle('menu-open');button.setAttribute('aria-expanded',String(open));}
  if(button.hasAttribute('data-search-toggle')){const open=$('.site-header').classList.toggle('search-open');button.setAttribute('aria-expanded',String(open));if(open)$('#global-search').focus();}
  if(button.dataset.scroll){const rail=document.getElementById(button.dataset.scroll);rail?.scrollBy({left:rail.clientWidth*.85*Number(button.dataset.direction),behavior:state.prefs.motion?'smooth':'instant'});}
  if(button.dataset.hero!==undefined){state.heroIndex=Number(button.dataset.hero);$('#page-content').innerHTML=homeMarkup();bindShell();}
  if(button.dataset.sort)updateCatalogParam('sort',button.dataset.sort);
  if(button.dataset.catalogPage){const params=route().params;params.set('page',button.dataset.catalogPage);nav('catalog?'+params);}
  if(button.dataset.saveId)await toggleSaved(button.dataset.saveId,button.dataset.saveKind);
  if(button.dataset.removeId){if(button.dataset.removeKind==='progress'){state.progress=state.progress.filter(entry=>entry.mediaId!==button.dataset.removeId);store.set('progress_'+(state.user?.id||'guest'),state.progress);render();}else await toggleSaved(button.dataset.removeId,button.dataset.removeKind,true);}
  if(button.hasAttribute('data-start-reading'))startReading();
  if(button.dataset.detailTab){for(const tab of $$('[data-detail-tab]')){const active=tab===button;tab.setAttribute('aria-selected',String(active));$('#detail-'+tab.dataset.detailTab).hidden=!active;}}
  if(button.hasAttribute('data-chapter-order')){const order=button.dataset.chapterOrder==='desc'?'asc':'desc';button.dataset.chapterOrder=order;button.innerHTML=(order==='desc'?'Mais recentes primeiro':'Primeiros capítulos')+icon('next');loadChapters(state.detail.id,renderVersion,1,order);}
  if(button.dataset.chapterPage)loadChapters(state.detail.id,renderVersion,Number(button.dataset.chapterPage));
  if(button.hasAttribute('data-all-chapters')){$('#chapter-language').value='all';loadChapters(state.detail.id,renderVersion);}
  if(button.dataset.spoiler){const text=document.getElementById('spoiler-'+button.dataset.spoiler);if(text){text.hidden=false;button.hidden=true;}}
  if(button.dataset.commentLike){if(!state.user){openAccount();return;}button.disabled=true;try{await post('/api/comments/'+encodeURIComponent(button.dataset.commentLike)+'/like',{});await loadComments(state.detail.id,renderVersion);}catch(error){toast(error.message,true);}finally{if(button.isConnected)button.disabled=false;}}
  if(button.dataset.commentDelete){button.disabled=true;try{await api('/api/comments/'+encodeURIComponent(button.dataset.commentDelete),{method:'DELETE'});await loadComments(state.detail.id,renderVersion);}catch(error){toast(error.message,true);button.disabled=false;}}
  if(button.dataset.pref){const key=button.dataset.pref;state.prefs[key]=!state.prefs[key];store.set('preferences',state.prefs);button.setAttribute('aria-checked',String(state.prefs[key]));applyPrefs();if(state.user)post('/api/settings',{settings:state.prefs}).catch(()=>toast('A preferência ficou neste navegador. A sincronização está indisponível.',true));}
  if(button.hasAttribute('data-logout')){button.disabled=true;try{await post('/api/auth/logout',{});state.user=null;clearTimeout(progressTimer);pendingProgress=null;restoreCollections();state.personalError='';nav('');toast('Você saiu da conta.');}catch(error){toast(error.message,true);button.disabled=false;}}
  if(button.hasAttribute('data-share')||button.hasAttribute('data-copy-profile')){const url=location.origin+location.pathname+location.hash;try{await navigator.clipboard.writeText(url);toast('Link copiado.');}catch{const input=document.createElement('input');input.value=url;input.readOnly=true;input.className='select-control';input.setAttribute('aria-label','Link para compartilhar');button.after(input);input.select();toast('Copie o link selecionado.');}}
  if(button.dataset.deleteImport)deleteImport(button.dataset.deleteImport);
  if(button.hasAttribute('data-sync'))loadPersonal();
  if(button.dataset.retry){if(button.dataset.retry==='home'){getCache.delete('/api/catalog/home');state.home=null;render();}else if(button.dataset.retry==='chapters')loadChapters(state.detail.id,renderVersion);else if(button.dataset.retry==='comments')loadComments(state.detail.id,renderVersion);else render();}
});
document.addEventListener('keydown',event=>{if(!event.target.matches?.('[data-detail-tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const tabs=$$('[data-detail-tab]'),index=tabs.indexOf(event.target);const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;event.preventDefault();tabs[next].focus();tabs[next].click();});
window.addEventListener('hashchange',()=>{if(location.hash==='#page-content'){$('#page-content')?.focus();return;}routeTrail.observe(location.hash);void flushProgress();render();});
window.addEventListener('scroll',()=>$('.site-header')?.classList.toggle('scrolled',window.scrollY>40),{passive:true});
window.addEventListener('dragover',event=>{if(route().page==='import')event.preventDefault();});window.addEventListener('drop',event=>{if(route().page==='import')event.preventDefault();});
window.addEventListener('pagehide',()=>{reader?.destroy();void flushProgress();});
restoreCollections();applyPrefs();render();
export {textPages,epubPages};
Promise.allSettled([api('/api/config'),api('/api/auth/me')]).then(async results=>{
  if(results[0].status==='fulfilled')state.config=results[0].value;
  if(results[1].status==='fulfilled'&&results[1].value.user?.id){state.user=results[1].value.user;clearTimeout(progressTimer);pendingProgress=null;restoreCollections();updateAccount();await loadPersonal();api('/api/settings').then(result=>{state.prefs={...state.prefs,...result.settings};store.set('preferences',state.prefs);applyPrefs();if(route().page==='settings')render();}).catch(()=>{});}
  state.authReady=true;updateAccount();if(['profile','settings'].includes(route().page))render();
});










